WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessions_transactions AS (SELECT id, account_id, txn_type, amount, txn_time, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT burst_id, account_id, MAX(txn_time) AS last_txn_time, MAX(txn_time) AS last_seen, MAX(txn_time) AS last_seen_2, GROUPING(burst_id) AS grouping_level FROM sessions_transactions GROUP BY CUBE (burst_id, account_id)
